/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;

  return {
    sortValue: decoded.slice(0, separatorAt),
    id: decoded.slice(separatorAt + 1),
  };
}

/**
 * The tenant predicate. Every repository read and write composes this — a
 * query that does not mention `org_id` is a cross-tenant leak waiting to
 * happen, so this is the only sanctioned way to express it.
 */
export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
  return eq(column, orgId);
}

/**
 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 * for archived rows. The `includeArchived` decision itself lives in
 * `shouldFilterArchived()` so it cannot drift per repository.
 */
export function livePredicate(
  column: SQLiteColumn,
  scope: ArchiveScope,
): SQL | undefined {
  return shouldFilterArchived(scope) ? isNull(column) : undefined;
}
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
/**
 * Cache tag vocabulary and revalidation helpers.
 *
 * Next 16 requires a cache-life profile as the second argument to
 * `revalidateTag`, which is exactly the kind of API change that rots when it
 * is spelled out at forty call sites. Server Actions call
 * `revalidateTagged([...])` and never import `next/cache` themselves.
 */
import { revalidateTag } from "next/cache";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

/** The cache-life profiles this app uses, by how stale a read may be. */
export const CACHE_PROFILES: Readonly<
  Record<"seconds" | "minutes" | "hours", string>
> = {
  seconds: "seconds",
  minutes: "minutes",
  hours: "hours",
};

export function orgTag(orgId: OrgId): string {
  return `org:${orgId}`;
}

export function projectTag(projectId: ProjectId): string {
  return `project:${projectId}`;
}

export function issueTag(issueId: IssueId): string {
  return `issue:${issueId}`;
}

/**
 * Invalidates every supplied tag under one profile, de-duplicating first so a
 * caller can splice together tag lists without worrying about repeats.
 */
export function revalidateTagged(
  tags: readonly string[],
  profile: string = CACHE_PROFILES.minutes,
): void {
  for (const tag of new Set(tags)) {
    if (tag === "") continue;
    revalidateTag(tag, profile);
  }
}
"use client";

/**
 * Bridges react-hook-form submission to a Server Action's `ActionResult`.
 *
 * Actions never throw for expected failures — they return
 * `{ ok: false, error }` so the form can render field errors without an error
 * boundary. This hook keeps that contract in one place: expected failures land
 * in `error`, and anything that genuinely throws is normalised by
 * `toAppError()` so the caller only ever sees an `AppErrorShape`.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { toAppError } from "@/lib/errors";
import type { ActionResult, AppErrorShape } from "@/types/api";

export type FormActionOptions = {
  onSuccess?: () => void;
  onError?: (error: AppErrorShape) => void;
  resetOnSuccess?: boolean;
};

export function useFormAction<TInput, TData>(
  action: (input: TInput) => Promise<ActionResult<TData>>,
  options?: FormActionOptions,
): {
  submit: (input: TInput) => Promise<void>;
  pending: boolean;
  error: AppErrorShape | null;
} {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<AppErrorShape | null>(null);

  // Callers pass an inline options object; a ref keeps `submit` stable so the
  // form does not re-register its handler on every render.
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  const submit = useCallback(
    async (input: TInput): Promise<void> => {
      const current = optionsRef.current;
      setPending(true);
      try {
        const result = await action(input);
        if (result.ok) {
          if (current?.resetOnSuccess !== false) setError(null);
          current?.onSuccess?.();
        } else {
          setError(result.error);
          current?.onError?.(result.error);
        }
      } catch (thrown) {
        const appError = toAppError(thrown);
        setError(appError);
        current?.onError?.(appError);
      } finally {
        setPending(false);
      }
    },
    [action],
  );

  return { submit, pending, error };
}
/**
 * Placeholder branded ids for `can()` calls about rows that do not exist yet.
 *
 * `PermissionResource` is a closed discriminated union, so asking "may this
 * actor create an issue in this project?" still has to name an `issueId`. The
 * ownership escalations inside `can()` compare ids for equality, and an empty
 * string never matches a real ULID — so a create check falls through to the
 * role matrix, which is exactly the intent.
 */

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
} from "@/types/common";

export const PENDING_ISSUE_ID = "" as IssueId;
export const PENDING_PROJECT_ID = "" as ProjectId;
export const PENDING_COMMENT_ID = "" as CommentId;
export const PENDING_MEMBER_ID = "" as MemberId;

/**
 * Bucket owner for rate limits consumed before any tenant is known — the login
 * and password-reset flows, which are reachable without a session.
 */
export const ANONYMOUS_ORG_ID = "" as OrgId;

