    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
/**
 * Cache tag vocabulary and revalidation helpers.
 *
 * Next 16 requires a cache-life profile as the second argument to
 * `revalidateTag`, which is exactly the kind of API change that rots when it
 * is spelled out at forty call sites. Server Actions call
 * `revalidateTagged([...])` and never import `next/cache` themselves.
 */
import { revalidateTag } from "next/cache";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

/** The cache-life profiles this app uses, by how stale a read may be. */
export const CACHE_PROFILES: Readonly<
  Record<"seconds" | "minutes" | "hours", string>
> = {
  seconds: "seconds",
  minutes: "minutes",
  hours: "hours",
};

export function orgTag(orgId: OrgId): string {
  return `org:${orgId}`;
}

export function projectTag(projectId: ProjectId): string {
  return `project:${projectId}`;
}

export function issueTag(issueId: IssueId): string {
  return `issue:${issueId}`;
}

/**
 * Invalidates every supplied tag under one profile, de-duplicating first so a
 * caller can splice together tag lists without worrying about repeats.
 */
export function revalidateTagged(
  tags: readonly string[],
  profile: string = CACHE_PROFILES.minutes,
): void {
  for (const tag of new Set(tags)) {
    if (tag === "") continue;
    revalidateTag(tag, profile);
  }
}
"use client";

/**
 * Bridges react-hook-form submission to a Server Action's `ActionResult`.
 *
 * Actions never throw for expected failures — they return
 * `{ ok: false, error }` so the form can render field errors without an error
 * boundary. This hook keeps that contract in one place: expected failures land
 * in `error`, and anything that genuinely throws is normalised by
 * `toAppError()` so the caller only ever sees an `AppErrorShape`.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { toAppError } from "@/lib/errors";
import type { ActionResult, AppErrorShape } from "@/types/api";

export type FormActionOptions = {
  onSuccess?: () => void;
  onError?: (error: AppErrorShape) => void;
  resetOnSuccess?: boolean;
};

export function useFormAction<TInput, TData>(
  action: (input: TInput) => Promise<ActionResult<TData>>,
  options?: FormActionOptions,
): {
  submit: (input: TInput) => Promise<void>;
  pending: boolean;
  error: AppErrorShape | null;
} {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<AppErrorShape | null>(null);

  // Callers pass an inline options object; a ref keeps `submit` stable so the
  // form does not re-register its handler on every render.
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  const submit = useCallback(
    async (input: TInput): Promise<void> => {
      const current = optionsRef.current;
      setPending(true);
      try {
        const result = await action(input);
        if (result.ok) {
          if (current?.resetOnSuccess !== false) setError(null);
          current?.onSuccess?.();
        } else {
          setError(result.error);
          current?.onError?.(result.error);
        }
      } catch (thrown) {
        const appError = toAppError(thrown);
        setError(appError);
        current?.onError?.(appError);
      } finally {
        setPending(false);
      }
    },
    [action],
  );

  return { submit, pending, error };
}
/**
 * Placeholder branded ids for `can()` calls about rows that do not exist yet.
 *
 * `PermissionResource` is a closed discriminated union, so asking "may this
 * actor create an issue in this project?" still has to name an `issueId`. The
 * ownership escalations inside `can()` compare ids for equality, and an empty
 * string never matches a real ULID — so a create check falls through to the
 * role matrix, which is exactly the intent.
 */

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
} from "@/types/common";

export const PENDING_ISSUE_ID = "" as IssueId;
export const PENDING_PROJECT_ID = "" as ProjectId;
export const PENDING_COMMENT_ID = "" as CommentId;
export const PENDING_MEMBER_ID = "" as MemberId;

/**
 * Bucket owner for rate limits consumed before any tenant is known — the login
 * and password-reset flows, which are reachable without a session.
 */
export const ANONYMOUS_ORG_ID = "" as OrgId;

