/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type { OrgId, Page } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`status:done`) is an `advanced_search` feature, so a query containing a
 * colon is rejected for plans that do not include it rather than silently
 * being treated as literal text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.q.includes(":") && !advanced) {
    throw new Error("Field-scoped search is not included in this plan");
  }

  const page = await searchRepo.searchDocuments(input);

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, input.q),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
---JOB
/**
 * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.
 *
 * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload
 */
import { getPlanLimits } from "@/config/plan-limits";
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { signPayload } from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** How many deliveries one pass claims. */
const CLAIM_BATCH = 25;

/** Attempts after which a delivery is marked failed for good. */
const MAX_ATTEMPTS = 6;

const logger = createLogger("webhook-delivery-job");

/**
 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
 * corpus builds and runs offline — so "delivery" means computing the
 * signature the receiver would verify and logging the attempt. The retry
 * bookkeeping around it is the part that has to be right.
 */
export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
  return runJob("webhook-delivery", async (result) => {
    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);

    for (const delivery of claimed) {
      const orgId = delivery.orgId as OrgId;

      if (!(await orgAllowsWebhooks(orgId))) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "webhooks are not included in this organization's plan",
        );
        result.failed += 1;
        continue;
      }

      if (delivery.attempts > MAX_ATTEMPTS) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          `giving up after ${delivery.attempts} attempts`,
        );
        result.failed += 1;
        continue;
      }

      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
        (row) => row.id === delivery.endpointId,
      );

      if (!endpoint || !endpoint.enabled) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "endpoint is missing or disabled",
        );
        result.failed += 1;
        continue;
      }

      const signature = signPayload(endpoint.secret, delivery.payload);

      logger.info("webhook delivered", {
        deliveryId: delivery.id,
        endpoint: endpoint.url,
        eventType: delivery.eventType,
        signature: signature.slice(0, 16),
        backoffMs: backoffMs(delivery.attempts),
      });

      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));
      result.processed += 1;
    }
  });
}

/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */
export function backoffMs(attempts: number): number {
  if (attempts <= 0) return 0;
  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);
}

async function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return false;

  if (getPlanLimits(org.plan).webhooks <= 0) return false;
  return isEnabled("webhooks", buildFlagContext(null, org));
}
---SCHED
/**
 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
 */
import { createLogger } from "@/lib/logger";
import { drain, enqueue, pendingCount } from "./queue";
import { toIsoTimestamp } from "@/types/common";
import type { JobKind } from "./queue";

/** How often `tick()` runs once the scheduler is started. */
const TICK_INTERVAL_MS = 60_000;

/** Minimum gap between two runs of the same job kind, in minutes. */
const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
  "digest-email": 60,
  "overdue-issues": 60,
  "webhook-delivery": 1,
  "usage-rollup": 15,
  "search-reindex": 1_440,
  "cleanup-archived": 1_440,
  "trial-expiry": 360,
};

const logger = createLogger("job-scheduler");

let timer: ReturnType<typeof setInterval> | null = null;
const lastRunAt = new Map<JobKind, number>();

/**
 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
 * keeps a process alive — a scheduler that blocks shutdown is worse than one
 * that misses the last tick.
 */
export function startScheduler(): void {
  if (timer !== null) return;

  timer = setInterval(() => {
    void tick(new Date()).catch((error: unknown) => {
      logger.error("scheduler tick failed", {
        reason: error instanceof Error ? error.message : String(error),
      });
    });
  }, TICK_INTERVAL_MS);

  timer.unref?.();
  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
}

export function stopScheduler(): void {
  if (timer === null) return;
  clearInterval(timer);
  timer = null;
  lastRunAt.clear();
}

export function isSchedulerRunning(): boolean {
  return timer !== null;
}

/**
 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
 * out from the interval so tests can drive it with an explicit clock instead
 * of waiting a minute.
 */
export async function tick(now: Date): Promise<void> {
  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
    if (!isDue(kind, now)) continue;

    lastRunAt.set(kind, now.getTime());
    enqueue({
      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
      kind,
      runAt: toIsoTimestamp(now),
      attempts: 0,
      payload: {},
    });
  }

  const completed = await drain();
  if (completed > 0 || pendingCount() > 0) {
    logger.debug("tick complete", { completed, pending: pendingCount() });
  }
}

function isDue(kind: JobKind, now: Date): boolean {
  const previous = lastRunAt.get(kind);
  if (previous === undefined) return true;
  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
}
 */
async function runHandler(job: QueuedJob): Promise<void> {
  const now = new Date();

  switch (job.kind) {
    case "digest-email": {
      const { runDigestEmailJob } = await import("./digest-email-job");
      await runDigestEmailJob(now);
      return;
    }
    case "overdue-issues": {
      const { runOverdueIssueJob } = await import("./overdue-issue-job");
      await runOverdueIssueJob(now);
      return;
    }
    case "webhook-delivery": {
      const { runWebhookDeliveryJob } = await import("./webhook-delivery-job");
      await runWebhookDeliveryJob(now);
      return;
    }
    case "usage-rollup": {
      const { runUsageRollupJob } = await import("./usage-rollup-job");
      await runUsageRollupJob(now);
      return;
    }
    case "search-reindex": {
      const { runSearchReindexJob } = await import("./search-reindex-job");
      const orgId = job.payload.orgId;
      if (typeof orgId !== "string") return;
      await runSearchReindexJob(orgId as Parameters<typeof runSearchReindexJob>[0]);
      return;
    }
    case "cleanup-archived": {
      const { runCleanupArchivedJob } = await import("./cleanup-archived-job");
      await runCleanupArchivedJob(now);
      return;
    }
    case "trial-expiry": {
      const { runTrialExpiryJob } = await import("./trial-expiry-job");
      await runTrialExpiryJob(now);
      return;
    }
  }
}

